#!/usr/bin/env bash
# Generated by Claude (Opus 5.5), 2026-10-04
# bench.sh - build and run bench-aggregates, and compare against a git commit.
#
# Usage (from anywhere inside the repo):
#   bench.sh              compare the working tree against HEAD
#   bench.sh <git-ref>    compare the working tree against that commit
#   bench.sh --run-only   run the working tree only and print its numbers
#   bench.sh --cross      cross-build a static x86-64 binary of the working tree
#                         (build/x86_64/bench-aggregates) to copy to the Intel box
#
# The comparison builds two binaries from the same bench-aggregates.cpp and
# tick-generator.hpp: one against the headers at <git-ref> (the baseline), one
# against the working tree. They run alternately on the same core, and
# bench-compare.py prints old and new ns per tick with the change.
#
# Environment:
#   CXX, CXXFLAGS   compiler and flags (default: g++-14, -O2 -march=native -DNDEBUG)
#   ROUNDS          baseline/current alternations (default: 3)
#   REPS            repetitions per benchmark in each round (default: 3)
#   MIN_TIME        measuring time per repetition (default: 0.1s)
#   FILTER          regex of benchmarks to run (default: all with --run-only; for a
#                   comparison, path|corpus, plus percall on x86-64)
#   NOISE           changes below this many percent are not reported (default: 5)
#   CORE            CPU core to pin to (default: the isolated core if the kernel
#                   has one, otherwise the last core)
#   XCXX, XMARCH    cross-compiler and target CPU for --cross
#                   (default: x86_64-linux-gnu-g++-14, ivybridge)
set -euo pipefail

SRC="$(cd "$(dirname "$0")" && pwd)"
ROOT="$(git -C "$SRC" rev-parse --show-toplevel)"
BUILD="$ROOT/build"
REL="${SRC#"$ROOT"/}"

CXX="${CXX:-g++-14}"
CXXFLAGS="${CXXFLAGS:--O2 -march=native -DNDEBUG}"
MIN_TIME="${MIN_TIME:-0.1s}"
if [ -z "${CORE:-}" ]; then
    # Prefer a core set aside with isolcpus= (the last one if there are several).
    ISOLATED="$(cat /sys/devices/system/cpu/isolated 2>/dev/null || true)"
    if [ -n "$ISOLATED" ]; then
        CORE="${ISOLATED##*[,-]}"
    else
        CORE="$(($(nproc) - 1))"
    fi
fi

mkdir -p "$BUILD"

build() { # source-dir  output
    # shellcheck disable=SC2086
    "$CXX" -std=c++23 $CXXFLAGS "$1/bench-aggregates.cpp" -lbenchmark -lpthread -o "$2"
}

run() { # binary  extra flags...
    local bin="$1"; shift
    local pin=()
    command -v taskset >/dev/null && pin=(taskset -c "$CORE")
    "${pin[@]}" "$bin" --benchmark_min_time="$MIN_TIME" "$@"
}

if [ "${1:-}" = "--run-only" ]; then
    build "$SRC" "$BUILD/bench-aggregates"
    run "$BUILD/bench-aggregates" --benchmark_filter="${FILTER:-.}" \
        --benchmark_repetitions="${REPS:-1}" --benchmark_display_aggregates_only=true
    exit 0
fi

if [ "${1:-}" = "--cross" ]; then
    X="$BUILD/x86_64"
    XCXX="${XCXX:-x86_64-linux-gnu-g++-14}"
    XMARCH="${XMARCH:-ivybridge}"
    command -v "$XCXX" >/dev/null || {
        echo "$XCXX not found. Install it with: sudo apt install g++-14-x86-64-linux-gnu" >&2
        exit 1
    }
    mkdir -p "$X"
    # Google Benchmark for x86-64, built once as a static library.
    if [ ! -f "$X/prefix/lib/libbenchmark.a" ]; then
        echo "Building Google Benchmark for x86-64 (first time only)..."
        [ -d "$X/benchmark-src" ] || git clone -q --depth 1 --branch v1.8.3 \
            https://github.com/google/benchmark.git "$X/benchmark-src" 2>/dev/null
        cmake -S "$X/benchmark-src" -B "$X/benchmark-build" \
            -DCMAKE_SYSTEM_NAME=Linux -DCMAKE_SYSTEM_PROCESSOR=x86_64 \
            -DCMAKE_C_COMPILER="${XCXX/g++/gcc}" -DCMAKE_CXX_COMPILER="$XCXX" \
            -DCMAKE_BUILD_TYPE=Release -DBUILD_SHARED_LIBS=OFF \
            -DBENCHMARK_ENABLE_TESTING=OFF -DBENCHMARK_ENABLE_GTEST_TESTS=OFF \
            -DBENCHMARK_ENABLE_WERROR=OFF -DBENCHMARK_ENABLE_LIBPFM=OFF \
            -DCMAKE_INSTALL_PREFIX="$X/prefix" >"$X/cmake.log" 2>&1
        cmake --build "$X/benchmark-build" -j"$(nproc)" >"$X/build.log" 2>&1
        cmake --install "$X/benchmark-build" >"$X/install.log" 2>&1
    fi
    # Static, so the binary does not depend on the libraries on the target.
    "$XCXX" -std=c++23 -O2 -march="$XMARCH" -DNDEBUG -static -I"$X/prefix/include" \
        "$SRC/bench-aggregates.cpp" -L"$X/prefix/lib" -lbenchmark -lpthread \
        -o "$X/bench-aggregates"
    if command -v qemu-x86_64 >/dev/null; then
        # Emulated: proves the binary starts and the timer code runs. Timings mean nothing.
        qemu-x86_64 "$X/bench-aggregates" --benchmark_filter='10x1ms' \
            --benchmark_min_time=0.01s >/dev/null 2>&1 \
            && echo "Smoke test under qemu: ok" || echo "Smoke test under qemu: FAILED" >&2
    fi
    echo "Built $X/bench-aggregates (x86-64, -march=$XMARCH, static)"
    echo "On the target: taskset -c 3 ./bench-aggregates --benchmark_repetitions=9"
    exit 0
fi

REF="${1:-HEAD}"
ROUNDS="${ROUNDS:-3}"
REPS="${REPS:-3}"
if [ -z "${FILTER:-}" ]; then
    # Per-call percentiles need a fine-grained clock; see bench-aggregates.cpp.
    case "$(uname -m)" in x86_64) FILTER="." ;; *) FILTER="path|corpus" ;; esac
fi

# Baseline: the sources at REF, with today's benchmark and tick generator on top.
BASE_SRC="$BUILD/bench-baseline-src"
rm -rf "$BASE_SRC"
mkdir -p "$BASE_SRC"
git -C "$ROOT" archive "$REF" "$REL" | tar -x -C "$BASE_SRC"
cp "$SRC/bench-aggregates.cpp" "$SRC/tick-generator.hpp" "$BASE_SRC/$REL/"

echo "Building baseline ($REF) and working tree..."
build "$BASE_SRC/$REL" "$BUILD/bench-aggregates-baseline"
build "$SRC" "$BUILD/bench-aggregates"

flags=(--benchmark_filter="$FILTER" --benchmark_repetitions="$REPS"
       --benchmark_enable_random_interleaving=true --benchmark_out_format=json)

rm -f "$BUILD"/bench-baseline-*.json "$BUILD"/bench-current-*.json
for round in $(seq "$ROUNDS"); do
    echo "Round $round of $ROUNDS..."
    run "$BUILD/bench-aggregates-baseline" "${flags[@]}" \
        --benchmark_out="$BUILD/bench-baseline-$round.json" >"$BUILD/bench-baseline.log" 2>&1
    run "$BUILD/bench-aggregates" "${flags[@]}" \
        --benchmark_out="$BUILD/bench-current-$round.json" >"$BUILD/bench-current.log" 2>&1
done

echo
echo "Baseline: $REF ($(git -C "$ROOT" rev-parse --short "$REF"))   New: working tree"
python3 "$SRC/bench-compare.py" --noise "${NOISE:-5}" \
    --baseline "$BUILD"/bench-baseline-*.json --current "$BUILD"/bench-current-*.json
